def bfsdist(seen,start):
    q=deque([start]); d={start:0}
    while q:
        p=q.popleft()
        for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]:
            x=(p[0]+dr,p[1]+dc)
            if x in seen and x not in d:d[x]=d[p]+1;q.append(x)
    return d
